#include "re3_codec.h"
#include <stdio.h>
int main(void){re3c_fx a,b,c,w0,w1;re3c_vec3fx p0,p1,o;re3c_u8 cmd[6]={0x2A,0,3,2,0x34,0x12};re3c_parts_set_cmd pc;if(!re3c_check_host()){puts("FAIL host widths");return 1;}a=re3c_fx_from_int(3);b=re3c_fx_from_int(2);c=re3c_fx_mul(a,b);if(re3c_fx_to_int(c)!=6){puts("FAIL fixed mul");return 1;}if(re3c_bind_blend_q7_to_fx(64u,&w0,&w1)!=RE3C_OK||w0!=2048||w1!=2048){puts("FAIL q7 weights");return 1;}p0.x=p0.y=p0.z=0;p1.x=re3c_fx_from_int(10);p1.y=p1.z=0;if(re3c_bind_blend_positions_q7(&p0,&p1,64u,&o)!=RE3C_OK||re3c_fx_to_int(o.x)!=5){puts("FAIL q7 blend");return 1;}if(re3c_decode_parts_set(cmd,sizeof(cmd),&pc)!=RE3C_OK||pc.id!=3u||pc.type!=2u||pc.value!=0x1234){puts("FAIL parts_set");return 1;}if(re3c_psx_color_to_argb(0u)!=0u){puts("FAIL transparent zero");return 1;}if(re3c_psx_color_to_argb(0x8000u)!=0xFF000000u){puts("FAIL STP black");return 1;}puts("PASS synthetic RE3 core primitives");return 0;}
